function resolveWinner(declarations) {
  const importantOnes = declarations.filter((d) => d.important);
  const pool = importantOnes.length > 0 ? importantOnes : declarations;
  let best = pool[0];
  for (const d of pool.slice(1)) {
    const cmp = compareSpecificity(calculateSpecificity(d.parts), calculateSpecificity(best.parts));
    if (cmp > 0 || (cmp === 0 && d.order > best.order)) best = d;
  }
  return declarations.indexOf(best);
}
