function resolveLayerWinner(layerOrder, declA, declB) {
  if (declA.important && !declB.important) return 'A';
  if (declB.important && !declA.important) return 'B';
  const aUnlayered = declA.layer == null;
  const bUnlayered = declB.layer == null;
  if (aUnlayered && !bUnlayered) return 'A';
  if (bUnlayered && !aUnlayered) return 'B';
  if (aUnlayered && bUnlayered) return 'TIE';
  const aIdx = layerOrder.indexOf(declA.layer);
  const bIdx = layerOrder.indexOf(declB.layer);
  return aIdx > bIdx ? 'A' : bIdx > aIdx ? 'B' : 'TIE';
}

